<?php declare(strict_types=1);namespace StudPulse\Database;use PDO;use StudPulse\Config;final class DB{private static?PDO$pdo=null;public static function connection():PDO{if(self::$pdo){return self::$pdo;}Config::validate();$u=parse_url(Config::get('DATABASE_URL'));if(!$u||!isset($u['host'],$u['path'],$u['user'])){throw new \RuntimeException('Invalid database URL');}$name=ltrim($u['path'],'/');if(!preg_match('/^[a-zA-Z0-9_]+$/',$name)){throw new \RuntimeException('Invalid database name');}$pdo=new PDO('mysql:host='.$u['host'].';port='.($u['port']??3306).';dbname='.$name.';charset=utf8mb4',rawurldecode($u['user']),rawurldecode($u['pass']??''),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);$version=(string)$pdo->query('SELECT VERSION()')->fetchColumn();if(!preg_match('/^8\.0\./',$version)||stripos($version,'MariaDB')!==false){throw new \RuntimeException('BLOCKED_HOSTING: requires MySQL 8.0');}$pdo->exec("SET time_zone = '+00:00'");return self::$pdo=$pdo;}public static function run(string$sql,array$params=[]):\PDOStatement{$s=self::connection()->prepare($sql);$s->execute($params);return$s;}public static function one(string$sql,array$params=[]):?array{return self::run($sql,$params)->fetch()?:null;}public static function all(string$sql,array$params=[]):array{return self::run($sql,$params)->fetchAll();}public static function transaction(callable$fn):mixed{$p=self::connection();if($p->inTransaction()){return$fn();}$p->beginTransaction();try{$result=$fn();$p->commit();return$result;}catch(\Throwable$e){if($p->inTransaction()){$p->rollBack();}throw$e;}}public static function id():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);$h=bin2hex($b);return substr($h,0,8).'-'.substr($h,8,4).'-'.substr($h,12,4).'-'.substr($h,16,4).'-'.substr($h,20);}}